import{_ as t,o as s,c as d,a2 as i}from"./chunks/framework.D9E58p8B.js";const p=JSON.parse('{"title":"Touché","description":"","frontmatter":{"title":"Touché"},"headers":[],"relativePath":"reference/touche.md","filePath":"reference/touche.md"}'),o={name:"reference/touche.md"};function r(a,e,n,l,u,c){return s(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="touche-lire-l-arbre-d-accessibilite" tabindex="-1">Touché : lire l&#39;arbre d&#39;accessibilité <a class="header-anchor" href="#touche-lire-l-arbre-d-accessibilite" aria-label="Permalink to &quot;Touché : lire l&#39;arbre d&#39;accessibilité&quot;">​</a></h1><p>Touché est l&#39;organe de lecture structurelle : il renvoie les éléments d&#39;une interface (rôle, libellé, position) tels que le système les expose via l&#39;accessibilité, expurgés des contenus sensibles. Les descriptions des outils parlent d&#39;« arbre d&#39;accessibilité macOS ». Les deux outils sont en lecture seule et ne sont pas soumis au plafond des Mains.</p><table tabindex="0"><thead><tr><th>Outil</th><th>Rôle</th><th>Niveau</th></tr></thead><tbody><tr><td><a href="#touche-tree"><code>touche_tree</code></a></td><td>Arbre borné et expurgé d&#39;une fenêtre</td><td>lecture</td></tr><tr><td><a href="#touche-probe"><code>touche_probe</code></a></td><td>Élément situé sous un point de l&#39;écran</td><td>lecture</td></tr></tbody></table><p><strong>Prérequis</strong> : l&#39;autorisation Accessibilité du système doit être accordée au processus responsable de Daimon. Sans elle, les deux outils renvoient <code>accessibility_permission_denied</code>. <code>daimon_doctor</code> vérifie cette autorisation sans jamais ouvrir de boîte de dialogue.</p><h2 id="erreurs-communes" tabindex="-1">Erreurs communes <a class="header-anchor" href="#erreurs-communes" aria-label="Permalink to &quot;Erreurs communes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Signification</th></tr></thead><tbody><tr><td><code>accessibility_permission_denied</code></td><td>L&#39;autorisation Accessibilité manque</td></tr><tr><td><code>excluded</code></td><td>La cible appartient à une application protégée par vos exclusions</td></tr><tr><td><code>snapshot_failed</code></td><td>La lecture de l&#39;arbre a échoué</td></tr></tbody></table><h2 id="touche-tree" tabindex="-1">touche_tree <a class="header-anchor" href="#touche-tree" aria-label="Permalink to &quot;touche_tree {#touche-tree}&quot;">​</a></h2><p>Renvoie l&#39;arbre d&#39;accessibilité, borné en profondeur et expurgé.</p><table tabindex="0"><thead><tr><th>Paramètre</th><th>Type</th><th>Défaut</th><th>Obligatoire</th><th>Rôle</th></tr></thead><tbody><tr><td><code>max_depth</code></td><td>entier</td><td><code>4</code></td><td>non</td><td>Profondeur maximale du parcours depuis la racine</td></tr><tr><td><code>root</code></td><td>objet <code>{x, y}</code></td><td>racine de la fenêtre au premier plan</td><td>non</td><td>Point désignant la racine du sous-arbre</td></tr><tr><td><code>roles</code></td><td>liste de chaînes</td><td>aucun filtre</td><td>non</td><td>Filtre par rôle ; vide ou omis, aucun filtre</td></tr><tr><td><code>prune_empty</code></td><td>booléen</td><td><code>true</code></td><td>non</td><td>Élague les nœuds vides ou sans intérêt</td></tr><tr><td><code>summary</code></td><td>booléen</td><td><code>false</code></td><td>non</td><td>Renvoie un résumé texte compact plutôt que l&#39;arbre de nœuds</td></tr><tr><td><code>window</code></td><td>objet <code>{pid, bundle, title}</code></td><td>fenêtre au premier plan</td><td>non</td><td>Cible de fenêtre ; chaque champ est optionnel</td></tr></tbody></table><p><strong>Niveau</strong> : lecture.</p><p><strong>Exemple d&#39;appel</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;max_depth&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;roles&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;AXButton&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;summary&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;window&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;bundle&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.apple.finder&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre></div><p><strong>Retour</strong> : l&#39;arbre de nœuds expurgé, ou <code>{summary}</code> (une chaîne) quand <code>summary</code> est vrai, ou une erreur de contrat (voir ci-dessus).</p><p><strong>Pièges</strong></p><ul><li>Une profondeur élevée sur une application riche produit une réponse très volumineuse : préférez <code>summary</code>, <code>roles</code> ou un <code>root</code> ciblé.</li><li>Les valeurs de rôle sont celles de l&#39;accessibilité du système ; relevez-les d&#39;abord dans un arbre complet plutôt que de les deviner.</li><li>Un arbre vide ou muet (applications dessinées sur mesure) n&#39;est pas une erreur : utilisez alors <a href="./vue.html#vue-find"><code>vue_find</code></a>.</li><li>Fournissez le <code>role</code> et le <code>label</code> ainsi obtenus aux outils des Mains afin que Daimon puisse vérifier la réversibilité.</li></ul><h2 id="touche-probe" tabindex="-1">touche_probe <a class="header-anchor" href="#touche-probe" aria-label="Permalink to &quot;touche_probe {#touche-probe}&quot;">​</a></h2><p>Renvoie le seul élément d&#39;accessibilité situé sous un point de l&#39;écran, expurgé.</p><table tabindex="0"><thead><tr><th>Paramètre</th><th>Type</th><th>Défaut</th><th>Obligatoire</th><th>Rôle</th></tr></thead><tbody><tr><td><code>x</code></td><td>entier</td><td>aucun</td><td><strong>oui</strong></td><td>Abscisse du point d&#39;écran</td></tr><tr><td><code>y</code></td><td>entier</td><td>aucun</td><td><strong>oui</strong></td><td>Ordonnée du point d&#39;écran</td></tr></tbody></table><p><strong>Niveau</strong> : lecture.</p><p><strong>Exemple d&#39;appel</strong> : <code>{ &quot;x&quot;: 640, &quot;y&quot;: 420 }</code></p><p><strong>Retour</strong> : le nœud unique expurgé, ou une erreur de contrat (voir ci-dessus).</p><p><strong>Pièges</strong> : <code>x</code> et <code>y</code> sont des points du bureau global, la même unité que celle de <code>main_click</code>.</p>',22)])])}const b=t(o,[["render",r]]);export{p as __pageData,b as default};
